// 브라우저 탭을 강제 종료하면 '나감' 메시지는 안 온다
// → 만료(TTL) 방식으로 짜야 한다
const lastSeen = new Map();   // userId → 마지막 하트비트 시각
const TTL = 10_000;           // 10초 갱신 없으면 나간 것

// 하트비트: 각 클라가 3초마다 '나 있어'
onHeartbeat((userId) => lastSeen.set(userId, Date.now()));

// 주기적으로 만료 청소
setInterval(() => {
  const now = Date.now();
  for (const [id, t] of lastSeen)
    if (now - t > TTL) lastSeen.delete(id);   // TTL 지나면 제거(유령 방지)
}, 2000);
// '나감' 이벤트는 있으면 빠른 것일 뿐 — 정확성은 항상 TTL 이 만든다

// 움직임마다 전송 → 사람 10명이면 초당 수백 메시지
// 20~30ms 로 묶어서 마지막 위치만
let pending = null;
onMouseMove((p) => { pending = p; });   // 계속 덮어씀(최신만)

setInterval(() => {
  if (pending) { socket.send({ type: 'cursor', pos: pending }); pending = null; }
}, 30);   // 30ms 마다 한 번, 그 사이 마지막 위치만
// 받는 쪽은 보간(interpolate)해 부드럽게 — 커서는 최신만 의미 있음(덮어쓰기)

// 사용자 id 를 해시 → 색상환(hue). 같은 id 는 항상 같은 색
function hashHue(id) {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) % 360;
  return h;
}
const colorOf = (id) => `hsl(${hashHue(id)}, 65%, 60%)`;
// 새로고침·재접속해도 색 유지 → 누가 누군지 따라감
// 색만으로 구분 말고 이름표도(색맹·비슷한 색·많은 사람 — 접근성)
